class Solution{public String removeDuplicateLetters(String s){int[]last=new int[26];boolean[]used=new boolean[26];for(int i=0;i<s.length();i++)last[s.charAt(i)-'a']=i;StringBuilder r=new StringBuilder();for(int i=0;i<s.length();i++){char c=s.charAt(i);int k=c-'a';if(used[k])continue;while(r.length()>0&&r.charAt(r.length()-1)>c&&last[r.charAt(r.length()-1)-'a']>i){used[r.charAt(r.length()-1)-'a']=false;r.deleteCharAt(r.length()-1);}r.append(c);used[k]=true;}return r.toString();}}
